(function() {
  renderIndicateurs();
  initDenominatorPanel();
  updateInstitution();
  updatePrestationInstitution();
  bindDropdownCloseOnOutsideClick('criteria-dropdown');
  bindDropdownCloseOnOutsideClick('criteria-prest-dropdown');
})();
